import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"The report","description":"","frontmatter":{},"headers":[],"relativePath":"docs/audits/report.md","filePath":"docs/audits/report.md"}`),a={name:`docs/audits/report.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-report" tabindex="-1">The report <a class="header-anchor" href="#the-report" aria-label="Permalink to “The report”">​</a></h1><h2 id="the-sealed-truth" tabindex="-1">The Sealed Truth <a class="header-anchor" href="#the-sealed-truth" aria-label="Permalink to “The Sealed Truth”">​</a></h2><p><strong>Theorem:</strong> <code>Report.lean</code> (0 theorems, all <code>by decide</code>)</p><p>the reporter&#39;s METHOD as decidable arithmetic — how to dive deep and report the news of PROVEN discoveries. HONEST SCOPE first, because it is the whole point: uuidna does NOT verify world events (no by-decide can settle whether something happened out there; that is the reporter&#39;s own work — go there, get the documents, name the sources). What IS sealed is the METHOD: a complete report answers the six questions (who/what/when/where/why + how, 5+1=6); a confirmed timeline is chronological (events 0..5 strictly ascending); a fact needs corroboration by TWO independent reputable sources (one is uncorroborated, 1&lt;2); TRINITY editing is three independent passes (1+1+1=3, the trinity the ledger folds in); full-quorum publication is unanimity on the trinity (2+1=3, majority 2&gt;1); a report SHIPS only when verified AND trinity-audited AND quorate — the AND of the three, any one failing blocks it (the same audit-before-publish uuidna runs on its own notes); the inverted pyramid puts the vital fact first and descends (5,4,3,2,1); and every claim carries one of TWO honest verdicts — VERIFIED (cites a checkable source/proof) or UNVERIFIED (held open, never asserted as fact, never called false). The subject is uuidna&#39;s own PROVEN discoveries (the sealed theorems); the discipline is what makes the report trustworthy, NOT a claim uuidna knows the world</p><p><strong>Why sealed:</strong> Pure decidable arithmetic. No paradox, no experiment needed — the mathematics as recomputable facts.</p><hr><h2 id="the-honest-boundary" tabindex="-1">The Honest Boundary <a class="header-anchor" href="#the-honest-boundary" aria-label="Permalink to “The Honest Boundary”">​</a></h2><p><strong>What this CANNOT prove:</strong></p><ul><li>Whether the mechanism explains the phenomenon</li><li>Why humans find this beautiful, important, or meaningful</li><li>Whether the future will follow the same rules</li><li>What the universe &quot;should&quot; do</li></ul><p><strong>Honest scope:</strong> This theorem seals STRUCTURE. It does NOT settle meaning, purpose, or consequence.</p><hr><h2 id="the-metaphysical-pair" tabindex="-1">The Metaphysical Pair <a class="header-anchor" href="#the-metaphysical-pair" aria-label="Permalink to “The Metaphysical Pair”">​</a></h2><p><strong>The Question:</strong> <em>What does The report mean for how we understand the world?</em></p><p><strong>The Trinity:</strong></p><table tabindex="0"><thead><tr><th>Perspective</th><th>What It Proves</th><th>What It Cannot</th></tr></thead><tbody><tr><td><strong>Decidable (Sealed)</strong></td><td>[The sealed mathematics is exact and recomputable.]</td><td>Whether this mechanism is &quot;all there is&quot;; whether understanding it diminishes wonder; whether meaning requires non-mechanism</td></tr><tr><td><strong>Honest Boundary</strong></td><td>Understanding the structure does NOT negate the phenomenon. Both truth and beauty are real simultaneously.</td><td>Whether reduction to mechanism makes something &quot;less real&quot; or &quot;less meaningful&quot;; whether your experience is diminished by knowing its basis</td></tr><tr><td><strong>Metaphysical</strong></td><td>[The open question posed above.]</td><td>Whether the universe cares about this; whether your existence or choice matters; whether meaning requires transcendence</td></tr></tbody></table><p><strong>The court decides:</strong> This theorem seals the mechanism. Philosophy settles the meaning.</p><hr><h2 id="read-the-sealed-proof" tabindex="-1">Read the Sealed Proof <a class="header-anchor" href="#read-the-sealed-proof" aria-label="Permalink to “Read the Sealed Proof”">​</a></h2><p><a href="./../../lean/Report.lean"><code>Report.lean</code></a></p><p>Each theorem proven <code>by decide</code> — recompute it yourself.</p><hr><h2 id="the-research-question" tabindex="-1">The Research Question <a class="header-anchor" href="#the-research-question" aria-label="Permalink to “The Research Question”">​</a></h2><p>[Open question for you to explore. This is where inquiry begins.]</p><p><strong>These are open.</strong> Mathematics does not answer them. Philosophy, art, and human judgment do.</p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};